//! 📦️ Typed STEP and IDML jobs publish interoperable bytes through the real batch driver.
use super::*;
#[test]
fn typed_format_jobs_use_their_real_encoders_and_exact_media_contracts(){
    let mut doc=semio_s_artifact_layout_layout_model::io::text::snapshot::snapshot_wire_codec::default_document();doc.pages.truncate(1);let page_ids=doc.pages.iter().map(|page|page.id.clone()).collect::<Vec<_>>();for spread in &mut doc.spreads{spread.page_ids.retain(|id|page_ids.contains(id));}doc.spreads.retain(|spread|!spread.page_ids.is_empty());doc.links.clear();doc.background_drawing=None;doc.referenced_model=None;
    for page in &mut doc.pages{page.overrides.clear();page.frames.retain(|frame|!matches!(frame,Frame::Image{..}));let ids=page.frames.iter().map(|frame|frame.id().to_string()).collect::<Vec<_>>();for layer in &mut page.layers{layer.object_ids.retain(|id|ids.contains(id));}}
    let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../🚪️io/🔀️interchange/📦️idml/📎️overrides/🧪️fixtures/🔣️.json")).unwrap();let mut change:semio_s_artifact_layout_layout_model::PageOverride=semio_framework_pack_json::from_json_str(&fixture["cases"][0]["override"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let parent=doc.parent_pages.first().unwrap();change.object_id=parent.frames.first().unwrap().id().into();doc.pages[0].parent_page_id=Some(parent.id.clone());doc.pages[0].overrides=vec![change];
    for(kind,mime,extension)in[(LayoutExportKind::Step,"model/step","step"),(LayoutExportKind::Idml,"application/vnd.adobe.indesign-idml-package","idml")]{
        let commit=headless_batch_export(kind,&doc,None,None).unwrap();assert_eq!(commit.mime_type,mime);assert!(commit.filename.ends_with(extension));
        let bytes=if kind.binary(){decode_base64(&commit.data).unwrap()}else{commit.data.into_bytes()};
        if kind==LayoutExportKind::Step{assert!(bytes.starts_with(b"ISO-10303-21;"));let text=std::str::from_utf8(&bytes).unwrap();assert!(text.contains("MANIFOLD_SOLID_BREP"));assert!(text.contains("POLYLINE"));assert!(text.contains("TEXT_LITERAL_WITH_EXTENT"));}else{let imported=semio_s_artifact_layout_layout_io::interchange::import_document("idml",&bytes,"Job",&mut |_|true).unwrap();assert_eq!(imported.value.pages.len(),doc.pages.len());assert_eq!(imported.value.parent_pages.len(),doc.parent_pages.len());let change=&imported.value.pages[0].overrides[0];assert_eq!(change.object_id,doc.pages[0].overrides[0].object_id);assert_eq!(change.locked,Some(false));assert!((change.bounds.as_ref().unwrap().x-doc.pages[0].overrides[0].bounds.as_ref().unwrap().x).abs()<1e-8);assert_eq!(imported.value.stories.iter().map(|story|story.content.as_str()).collect::<Vec<_>>(),doc.stories.iter().map(|story|story.content.as_str()).collect::<Vec<_>>());}
    }
}

#[test]
fn pdf_job_semantic_unicode_reaches_editable_layout_through_the_canonical_artifact_importer(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../🚪️io/🔀️interchange/🧪️fixtures/🔣️.json")).unwrap();let case=fixture["cases"].as_array().unwrap().iter().find(|case|case["id"]=="pdf-editor-unicode-import").unwrap();let mut doc=semio_s_artifact_layout_layout_model::io::text::snapshot::snapshot_wire_codec::default_document();doc.pages.truncate(1);doc.parent_pages.clear();doc.links.clear();doc.background_drawing=None;doc.referenced_model=None;doc.pages[0].parent_page_id=None;doc.pages[0].overrides.clear();doc.pages[0].width=case["page"]["width"].as_f64().unwrap();doc.pages[0].height=case["page"]["height"].as_f64().unwrap();let page_id=doc.pages[0].id.clone();for spread in &mut doc.spreads{spread.page_ids.retain(|id|id==&page_id);}doc.spreads.retain(|spread|!spread.page_ids.is_empty());let story_id=doc.stories.first().unwrap().id.clone();doc.stories.truncate(1);doc.stories[0].content=case["page"]["text"].as_str().unwrap().into();doc.stories[0].style_runs.clear();let layer_id=doc.pages[0].layer_ids[0].clone();doc.pages[0].frames=vec![Frame::Text{id:"unicode-job-text".into(),layer_id:layer_id.clone(),bounds:semio_s_artifact_layout_layout_model::LayoutBounds{x:10.0,y:20.0,width:180.0,height:260.0,rotation:0.0},story_id,thread_next:None,columns:1,inset:semio_s_artifact_layout_layout_model::LayoutRect{x:0.0,y:0.0,width:0.0,height:0.0},wrap_mode:"none".into(),locked:None,visible:None}];for layer in &mut doc.pages[0].layers{layer.visible=true;layer.object_ids=if layer.id==layer_id{vec!["unicode-job-text".into()]}else{Vec::new()};}
 let commit=headless_batch_export(LayoutExportKind::Pdf,&doc,None,None).unwrap();let bytes=decode_base64(&commit.data).unwrap();let pdf=semio_s_artifact_stdio_pdf::standards::v1_7::subsets::base::io::import::decode_pdf(&bytes).unwrap();assert_eq!(semio_s_artifact_stdio_pdf::standards::v1_7::subsets::base::io::import::page_text(&pdf,0).unwrap().trim(),case["expected"]["text"].as_str().unwrap());let imported=semio_s_artifact_layout_layout_io::interchange::import_document("pdf",&bytes,"Unicode job",&mut |_|true).unwrap();let stories=imported.value.stories.iter().map(|story|story.content.as_str()).collect::<String>();assert_eq!(stories.trim(),case["expected"]["text"].as_str().unwrap());assert!(imported.value.pages[0].frames.iter().any(|frame|matches!(frame,Frame::Text{..})&&frame.bounds().x>0.0));for story in &imported.value.stories{assert!(story.style_runs.iter().all(|run|run.end<=story.content.len()as u64));}
}
